ALTER TABLE `permissions` MODIFY COLUMN `allowedOrgIds` text;
ALTER TABLE `permissions` MODIFY COLUMN `allowedUserIds` text;
ALTER TABLE `scorm_data` MODIFY COLUMN `cmiData` text

